SET TIME ZONE 'UTC';
DO $$ BEGIN CREATE ROLE anon; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE authenticated; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE service_role; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE SCHEMA auth; CREATE SCHEMA referral_private;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('test.uid',true),'')::uuid $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql AS $$ SELECT coalesce(nullif(current_setting('test.jwt',true),''),'{}')::jsonb $$;
CREATE FUNCTION public.referral_is_admin(uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT coalesce($1='00000000-0000-4000-8000-000000000001'::uuid,false) $$;
CREATE TABLE public.referral_program_settings(singleton boolean DEFAULT true,is_enabled boolean DEFAULT true,accrual_enabled boolean DEFAULT true,shadow_mode boolean DEFAULT false,hold_days integer DEFAULT 14,commission_percent_bps integer DEFAULT 1000,split_60_40_enabled boolean DEFAULT true,withdrawable_percent_bps integer DEFAULT 4000,commission_scheme text DEFAULT 'flat',club_first_payment_percent_bps integer DEFAULT 3000,tier_1_limit integer DEFAULT 5,tier_2_limit integer DEFAULT 5,tier_1_commission_percent_bps integer DEFAULT 1000,tier_2_commission_percent_bps integer DEFAULT 2000,tier_3_commission_percent_bps integer DEFAULT 3000);
CREATE TABLE public.orders_v2(id uuid PRIMARY KEY,profile_id uuid,product_id uuid,tariff_id uuid,offer_id uuid,status text DEFAULT 'paid',currency text DEFAULT 'BYN',paid_amount numeric DEFAULT 4500,is_deleted boolean DEFAULT false,meta jsonb DEFAULT '{}');
CREATE TABLE public.products_v2(id uuid PRIMARY KEY,referral_settings_mode text DEFAULT 'inherit',referral_commission_scheme text,referral_commission_percent_bps integer,referral_club_first_payment_percent_bps integer,referral_tier_1_limit integer,referral_tier_2_limit integer,referral_tier_1_commission_percent_bps integer,referral_tier_2_commission_percent_bps integer,referral_tier_3_commission_percent_bps integer);
CREATE TABLE public.referral_partners(id uuid PRIMARY KEY,profile_id uuid,status text DEFAULT 'active');
CREATE TABLE public.referral_relationships(id uuid PRIMARY KEY,partner_id uuid,referred_profile_id uuid,status text DEFAULT 'active',attached_at timestamptz DEFAULT now());
CREATE TABLE public.payments_v2(id uuid PRIMARY KEY,order_id uuid,status text DEFAULT 'succeeded',amount numeric DEFAULT 4500,is_recurring boolean DEFAULT false,is_deleted boolean DEFAULT false,refunded_amount numeric DEFAULT 0,transaction_type text,paid_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE public.referral_sale_attributions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid,relationship_id uuid,order_id uuid UNIQUE,payment_id uuid,product_id uuid,tariff_id uuid,offer_id uuid,status text,commission_basis_minor bigint,commission_basis_currency text,commission_percent_bps integer,commission_minor bigint,reversed_minor bigint DEFAULT 0,available_at timestamptz,rule_snapshot jsonb,order_snapshot jsonb,metadata jsonb DEFAULT '{}',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.referral_balance_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid,transaction_type text,idempotency_key text UNIQUE,source_type text,source_id uuid,description text);
CREATE TABLE public.referral_balance_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id uuid REFERENCES public.referral_balance_transactions(id),partner_id uuid,bucket text,amount_minor bigint);
CREATE TABLE public.audit_logs(id uuid DEFAULT gen_random_uuid(),actor_type text,actor_user_id uuid,action text,entity_type text,entity_id uuid,meta jsonb);
CREATE TABLE public.fixture_events(event text,sale_id uuid);
CREATE FUNCTION public.referral_emit_event(text,uuid,jsonb) RETURNS void LANGUAGE sql AS $$ INSERT INTO fixture_events VALUES($1,$2) $$;
